      root.querySelectorAll('[data-narr-vol]').forEach(x => { x.value = audioPrefs.vol; });
      if (!on) root.querySelectorAll('[data-gs-voice]').forEach(x => { const id = x.dataset.gsVoice; grossVoice(findBlock(id), false); });
